mapper.insert:
INSERT INTO player (service_id, name, paragon_level, mmr, `rank`) VALUES
(#{obj.serviceId},#{obj.name},#{obj.paragonLevel},#{obj.mmr},#{obj.rank})
ON DUPLICATE KEY UPDATE repeated_times = repeated_times + 1, name = VALUES(name),paragon_level = VALUES(paragon_level),`rank` = VALUES(`rank`),mmr = VALUES(mmr);
